gsl.gsl_function_cquad.argtypes = [c_type, ctypes.c_double, ctypes.c_double, ctypes.c_double, ctypes.c_double, ctypes.c_void_p]
gsl.gsl_function_cquad.restype = ctypes.c_double

class GSLFunction:
    def __init__(self, func):
        self.func = func

    def __call__(self, x):
        return self.func(x)

class CQuadWorkspace:
    def __init__(self, size):
        self.size = size

    def __del__(self):
        gsl.gsl_integration_cquad_free(self.size)


def integrate_function(func, a, b, epsabs, epsrel, workspace_size):
    c_func = c_type(GSLFunction(func))
    workspace = gsl.gsl_integration_cquad_workspace_alloc(workspace_size)
    result = gsl.gsl_integration_cquad(c_func, a, b, epsabs, epsrel, workspace)
    error = gsl.gsl_integration_cquad_error(workspace)
    n_evaluate = gsl.gsl_integration_cquad_n_evaluate(workspace)
    gsl.gsl_integration_cquad_free(workspace)
    return result, error, n_evaluate


