import numpy as np
import sys

class GSLMatrix(ctypes.Structure):
    _fields_ = []

def gsl_matrix_alloc(rows, cols):
    return ctypes.pointer(ctypes calloc(rows * cols * ctypes.sizeof(ctypes.c_double)))


def gsl_matrix_free(matrix):
    ctypes.free(matrix)


def numpy_to_gsl_matrix(np_array):
    matrix = gsl_matrix_alloc(np_array.shape[0], np_array.shape[1])
    for i in range(np_array.shape[0]):
        for j in range(np_array.shape[1]):
            ctypes.memmove(ctypes.byref(matrix.contents.data[i * cols + j]), 
                            ctypes.byref(np_array[i, j]), 
                            ctypes.sizeof(ctypes.c_double))
    return matrix


def gsl_matrix_to_numpy(matrix):
    np_array = np.zeros((matrix.contents.rows, matrix.contents.cols), dtype=np.float64)
    for i in range(matrix.contents.rows):
        for j in range(matrix.contents.cols):
            ctypes.memmove(ctypes.byref(np_array[i, j]), 
                            ctypes.byref(matrix.contents.data[i * cols + j]), 
                            ctypes.sizeof(ctypes.c_double))
    return np_array


def gsl_multifit_covar(jacobian, epsrel):
    # Load libraries
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

