    gsl_multifit_covar_func = gsl.gsl_multifit_covar
    gsl_multifit_covar_func.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_double, ctypes.c_int, ctypes.POINTER(ctypes.c_double)]
    gsl_multifit_covar_func.restype = ctypes.POINTER(ctypes.c_double)

    # Allocate covariance matrix
    cov_matrix = gsl_matrix_alloc(jacobian.contents.rows, jacobian.contents.cols)

    # Call function
    result = gsl_multifit_covar_func(jacobian, epsrel, jacobian.contents.cols, cov_matrix)

    # Convert to numpy array
    return gsl_matrix_to_numpy(result)


