# Helper functions
def complex_to_gsl_complex(c):
    return ctypes.pointer(ctypes.Structure._fields_([('real', ctypes.c_double(c.real)), ('imag', ctypes.c_double(c.imag))]))

def list_to_gsl_matrix_complex(matrix, size):
    gsl_matrix = gsl_matrix_complex_alloc(size)
    for i in range(size):
        for j in range(size):
            val = matrix[i][j]
            gsl_matrix_complex = ctypes.cast(gsl_matrix, ctypes.POINTER(ctypes.POINTER(ctypes.c_double)))
            gsl_matrix_complex[i][j] = ctypes.c_double(val.real)
            gsl_matrix_complex[i][j] + 1 = ctypes.c_double(val.imag)
    return gsl_matrix

