import ctypes

class GSLVector:
    _lib = None

    @classmethod
    def init_lib(cls):
        if cls._lib is None:
            cls._lib = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
            gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
            cls._lib = gsl

    @classmethod
    def create_vector(cls, size):
        cls.init_lib()
        return cls._lib.gsl_vector_alloc(size)

    @classmethod
    def set_vector_elements(cls, vec, values):
        cls.init_lib()
        for i in range(len(values)):
            cls._lib.gsl_vector_set(vec, i, values[i])

    @classmethod
    def get_vector_elements(cls, vec, size):
        cls.init_lib()
        result = (ctypes.c_double * size)()
        cls._lib.gsl_vector_get_elements(vec, result)
        return [result[i] for i in range(size)]


def create_and_manipulate_vector(values):
    size = len(values)
    vec = GSLVector.create_vector(size)
    GSLVector.set_vector_elements(vec, values)
    result = GSLVector.get_vector_elements(vec, size)
    return result

