        self._ptr = GSLVector._lib.gsl_vector_alloc(size)

    def __del__(self):
        GSLVector._lib.gsl_vector_free(self._ptr)

    def set_value(self, index, value):
        GSLVector._lib.gsl_vector_set(self._ptr, index, value)

    def get_value(self, index):
        return GSLVector._lib.gsl_vector_get(self._ptr, index)


