        self.func = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double)(function.callback)
        self.f1 = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double)(function.f1)
        self.f2 = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double)(function.f2)
        self.f3 = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double)(function.f3)

