        b_c = ctypes.c_double(b)
        epsabs_c = ctypes.c_double(epsabs)
        epsrel_c = ctypes.c_double(epsrel)
        limit_c = ctypes.c_int(limit)
        key_c = ctypes.c_int(key)

        # Create workspace
