class GSLMatrix(ctypes.Structure):
    _fields_ = [('data', ctypes.POINTER(ctypes.c_double)), ('size', ctypes.c_size_t)]

class GSLPermutation(ctypes.Structure):
    _fields_ = [('data', ctypes.POINTER(ctypes.c_int)), ('size', ctypes.c_size_t)]

def lu_decomposition(matrix):
    n = len(matrix)
    a = (ctypes.c_double * (n * n))()
    for i in range(n):
        for j in range(n):
            a[i * n + j] = ctypes.c_double(matrix[i][j])
    matrix_ptr = ctypes.pointer(GSLMatrix(a, n))

    perm = GSLPermutation(ctypes.pointer(ctypes.c_int * n)(), n)
    sign = ctypes.c_int(1)

    gsl.gsl_linalg_LU_decomp(matrix_ptr, ctypes.pointer(perm.data), ctypes.pointer(sign))

    result = [[0.0 for _ in range(n)] for _ in range(n)]
    for i in range(n):
        for j in range(n):
            result[i][j] = ctypes.c_double(a[i * n + j]).value
    return result, [x for x in perm.data], sign.value"}

