        gsl_chol_decomp.restype = ctypes.c_int
        work = (ctypes.c_double * self.n)()
        info = (ctypes.c_int * self.n)()
        gsl_chol_decomp(ctypes.pointer(self.matrix), self.n, ctypes.pointer(work), ctypes.pointer(info))
        lower = [[0.0 for _ in range(self.n)] for _ in range(self.n)]
        for i in range(self.n):
            for j in range(i + 1):
                lower[i][j] = self.matrix[i * self.n + j]
        return lower


