class gsl_function(ctypes.Structure):
    _fields_ = [
        ('function', ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double, ctypes.c_void_p)),
        ('params', ctypes.c_void_p)
    ]

def func_wrapper(x, params):
    py_func = ctypes.cast(params, ctypes.c_void_p).value
    return py_func(x)

def compute_integral(py_func, a, b, epsabs, epsrel, n):
    # Create function object
    func = gsl_function()
    func.function = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double, ctypes.c_void_p)(func_wrapper)
    func.params = ctypes.pointer(py_func)

    # Allocate Romberg workspace
    workspace = gsl.gsl_integration_romberg_alloc(n)

    # Compute integral
    result = gsl.gsl_integration_romberg(workspace, func, a, b, epsabs, epsrel)

    # Get number of function evaluations
    evaluations = ctypes.c_int()
    gsl.gsl_integration_romberg_get_evaluate(workspace, ctypes.byref(evaluations))

    # Free workspace
    gsl.gsl_integration_romberg_free(workspace)

    return result, evaluations.value

